import{_ as t,C as s,o as r,c as i,E as n,a2 as a}from"./chunks/framework.BXyf8PVu.js";const b=JSON.parse('{"title":"Musico","description":"","frontmatter":{"pageClass":"project-case-study","title":"Musico","order":5},"headers":[],"relativePath":"fr/projects/musico.md","filePath":"fr/projects/musico.md"}'),c={name:"fr/projects/musico.md"};function d(l,e,u,p,g,m){const o=s("ProjectHero");return r(),i("div",null,[n(o,{index:"05",eyebrow:"Génie logiciel · Audio natif",title:"Musico : lecteur musical natif hors ligne",summary:"Un lecteur audio local hors ligne, centré sur les dossiers et multi-files, développé nativement pour Apple, Android et Windows — sans aucun wrapper web, avec un moteur d’extensions JavaScript partagé.",year:"2025–2026",role:"Architecture, interface native et ingénierie audio",methods:"SwiftUI · Jetpack Compose · .NET 8 WPF · JavaScriptCore / QuickJS / Jint",chart:"/charts/musico-architecture.html?lang=fr","image-alt":"Schéma d’architecture interactif de Musico sur les clients natifs Apple, Android et Windows",docs:"https://musico.seanpnex.win/?lang=fr",repo:"https://github.com/SEANPNEX/Musico"}),e[0]||(e[0]=a('<h2 id="la-question" tabindex="-1">La question <a class="header-anchor" href="#la-question" aria-label="Permalink to &quot;La question&quot;">​</a></h2><p>La plupart des applications multiplateformes s’appuient sur Electron ou des WebViews embarquées, sacrifiant l’empreinte mémoire, les pipelines audio natifs et l’intégration système au profit d’une interface unique. Or, les auditeurs qui entretiennent de vastes bibliothèques locales privilégient deux usages souvent négligés par le streaming : préserver l’arborescence exacte de leurs dossiers et naviguer entre plusieurs files d’attente indépendantes sans perdre leur progression.</p><p><strong>Musico</strong> explore l’approche inverse : concevoir un lecteur hors ligne chaleureux et centré sur les dossiers (inspiré par <strong>Musicolet</strong> et <strong>YRRLYB/Aria</strong>) <strong>100 % natif</strong> pour Apple, Android et Windows, tout en unifiant le modèle de bibliothèque, la lecture et les extensions multiplateformes.</p><h2 id="trois-clients-natifs-zero-wrapper-web" tabindex="-1">Trois clients natifs, zéro wrapper web <a class="header-anchor" href="#trois-clients-natifs-zero-wrapper-web" aria-label="Permalink to &quot;Trois clients natifs, zéro wrapper web&quot;">​</a></h2><p>Chaque client s’appuie sur la pile graphique, le moteur audio et les contrôles multimédias natifs de son système, couplés à un moteur JavaScript léger embarqué pour les extensions :</p><table tabindex="0"><thead><tr><th>Client</th><th>Plateformes cibles</th><th>Pile technique</th><th>Design natif et intégration</th></tr></thead><tbody><tr><td><code>Musico/</code></td><td>iOS 17+, iPadOS, macOS (Catalyst)</td><td>Swift, SwiftUI (<code>@Observable</code>), <code>AVAudioEngine</code> + <code>AVAudioUnitEQ</code>, <code>MPNowPlayingInfoCenter</code>, <code>JavaScriptCore</code> (<code>Compression</code> + <code>CryptoKit</code>)</td><td>Apple HIG — onglets, feuilles et gestes de balayage iOS (<code>allowsFullSwipe: false</code> pour éviter toute suppression accidentelle de dossier, plus <strong>Annuler</strong> au balayage dans Files/Playlists) ; translucidité givrée <code>NSVisualEffectView</code>, couleur de barre latérale indépendante, palette de commandes <code>Cmd+K</code>, mini-lecteur flottant et glisser-déposer sur macOS</td></tr><tr><td><code>MusicoAndroid/</code></td><td>Android 8.0+ (API 26+)</td><td>Kotlin, Jetpack Compose, AndroidX Media3 (ExoPlayer + <code>MediaSessionService</code>), SAF <code>DocumentFile</code>, égaliseur <code>DynamicsProcessing</code>, <code>QuickJS</code> (<code>quickjs-kt</code>)</td><td>Material 3 / Material You — Dynamic Color, <code>NavigationBar</code> / <code>NavigationRail</code> adaptatifs, <code>ModalBottomSheet</code>, gestes de balayage en 2 temps Outlook × Material You <code>MusicoSwipeActionRow</code> (rail arrière découpé proprement, cran haptique, verrouillage du balayage sur la poignée <code>DragReorder</code> pour que <code>≡</code> ne coince jamais), sélecteurs segmentés sur une ligne sans coche encombrante, barres <code>MusicoSnackbarHost</code> à thème sombre avec <strong>Annuler</strong> sur la file, thèmes d’apparence personnalisés et suppression sur l’appareil / dossier <code>Musico</code></td></tr><tr><td><code>MusicoWindows/</code></td><td>Windows 10 (2004+) et Windows 11</td><td>C# / .NET 8 WPF, NAudio (égaliseur <code>BiQuadFilter</code> à 10 bandes), TagLibSharp, Windows 10 SMTC, <code>Jint</code></td><td>Fluent Design — coins arrondis / arrière-plan DWM et Acrylique de Windows 11, couleur et opacité indépendantes de la barre latérale, palette de commandes <code>Ctrl+K</code>, mini-lecteur flottant et glisser-déposer</td></tr></tbody></table><h2 id="fonctionnalites-cles" tabindex="-1">Fonctionnalités clés <a class="header-anchor" href="#fonctionnalites-cles" aria-label="Permalink to &quot;Fonctionnalités clés&quot;">​</a></h2><ul><li><strong>Bibliothèque centrée sur les dossiers, glisser-déposer et suppression sûre :</strong> montez vos répertoires locaux (<code>Music</code>, <code>Documents</code> ou dossiers personnalisés) en conservant leur hiérarchie intacte, ou déposez directement des dossiers locaux et fichiers audio sur la fenêtre macOS/Windows (les dossiers déposés sont montés dans <strong>Dossiers</strong> et les pistes lues immédiatement, tandis que les fichiers hors bibliothèque sont copiés dans le dossier musical par défaut). Si un disque est débranché ou un dossier déplacé, <strong>Relocate</strong> reconnecte les pistes sans perdre vos playlists ni votre historique d’écoute. La suppression distingue clairement <strong>Retirer de la bibliothèque</strong> de la suppression sur disque (<strong>Placer dans la corbeille</strong> sur macOS, <strong>Mettre dans la Corbeille</strong> sur Windows, <strong>Supprimer de l’appareil</strong> sur iOS/Android, y compris le dossier <code>Musico</code> d’Android). Lecture étendue lossless et lossy : FLAC, ALAC, WAV, AIFF, MP3, AAC/M4A (ainsi que OGG, Opus, WMA et WebM selon la plateforme).</li><li><strong>Dossiers cloud, OAuth 2.0 Drive optionnel et synchronisation hors ligne :</strong> montez directement dans <strong>Dossiers</strong> des sources publiques ou authentifiées par cookie — <strong>YouTube / YouTube Music</strong> (playlists, mix <code>RD</code>, albums, titres isolés), <strong>Bilibili</strong> (vidéos <code>BV</code>/<code>av</code> multi-parties, <code>favlist</code>, collections) et <strong>Google Drive</strong> (découverte récursive de dossiers et fichiers individuels). Les liens Drive publics ou partagés restent utilisables sans connexion, tandis que l’option <strong>Réglages → Compte Google Drive</strong> accepte l’ID client OAuth 2.0 d’application de bureau gratuit de l’utilisateur (<code>drive.readonly</code> + <code>userinfo.email</code>, mode Test, <code>http://127.0.0.1:&lt;port&gt;/oauth2callback</code> automatique, jeton Test de 7 jours avec <strong>Reconnecter Google Drive</strong>) pour les dossiers privés et le contournement de téléchargement des gros fichiers. Les morceaux peuvent être enregistrés localement avec un manifeste <code>.musico-cloud.json</code> et actualisés de façon incrémentale via <strong>Mettre à jour depuis le cloud</strong>.</li><li><strong>Files d’attente multiples et indépendantes, <code>Play Next</code> dédupliqué et balayage mobile :</strong> créez autant de files parallèles que d’humeurs ou de sessions d’écoute ; renommez, réorganisez, videz ou changez de file à tout moment, chacune conservant sa piste active, sa position de lecture, son ordre aléatoire et son mode de répétition (<code>Off</code> / <code>All</code> / <code>One</code>). Le <strong><code>Play Next</code> dédupliqué</strong> sur Apple, Android et Windows (<code>insertNext</code>) déplace proprement une occurrence existante non active dans la file au lieu de dupliquer le morceau, sans perturber la piste en cours de lecture. Des gestes de balayage mobile harmonisés proposent <strong>Lire ensuite</strong> vers la droite ; vers la gauche dans <strong>Titres</strong>, une boîte de confirmation <strong>Retirer de la bibliothèque</strong> / <strong>Supprimer de l’appareil</strong> s’ouvre (désactivée sur les aperçus cloud éphémères) ; vers la gauche dans <strong>Files</strong>, <strong>Playlists</strong> et <strong>Favoris</strong>, la suppression est immédiate avec <strong>Annuler</strong> restaurant la position exacte dans la file, l’index actif et l’horodatage de reprise ; enfin Android relève le seuil de suppression par balayage des dossiers (<code>~44%</code> / <code>min 140dp</code>) pour prévenir toute suppression accidentelle.</li><li><strong>Apparence unifiée et fonctions bureau avancées :</strong> les <strong>Réglages</strong> unifiés (<code>Cmd+,</code> / <code>Ctrl+,</code>) proposent les modes Système/Clair/Sombre, des préréglages d’arrière-plan et d’accentuation soignés, des sélecteurs de couleur hex/RVB/système, un <strong>aperçu En cours de lecture</strong> en direct, un <strong>contrôle de contraste WCAG 2.1</strong> intégré avec <strong>Correction auto du contraste</strong> en un clic, ainsi que des images d’arrière-plan personnalisées avec <strong>Visibilité de l’image</strong> (opacité) et <strong>Flou d’arrière-plan</strong>. Sur ordinateur s’ajoutent une <strong>Palette de commandes / Accès rapide</strong> globale (<code>Cmd+K</code> / <code>Ctrl+K</code>), une fenêtre <strong>Mini-lecteur flottant</strong> (<code>Cmd+Shift+N</code> / <code>Ctrl+Shift+N</code>) et des raccourcis clavier étendus (Paroles <code>Cmd+Shift+L</code> / <code>Ctrl+Shift+L</code> / <code>L</code>, File <code>Cmd+Shift+Q</code> / <code>Ctrl+Shift+Q</code> / <code>Q</code>, Avance/recul <code>±10s</code>, Volume <code>±5%</code>, Muet, Aléatoire/Répétition, En cours de lecture).</li><li><strong>Soins apportés à la lecture et à la bibliothèque :</strong><ul><li><strong>Égaliseur ISO 10 bandes</strong> (<code>31 Hz</code>–<code>16 kHz</code>) avec préampli de <code>-12 dB</code> à <code>+12 dB</code>, 8 préréglages et mode <code>Custom</code>.</li><li><strong>Paroles synchronisées et texte :</strong> priorité automatique <strong>Importées</strong> → <strong>Accompagnantes</strong> <code>.lrc</code>/<code>.txt</code> → <strong>Intégrées</strong>, horodatages multiples <code>.lrc</code>, décodage UTF-8 / UTF-16 BOM / GB18030, recherche tactile par ligne, taille de police et alignement personnalisables, et bouton <strong>Synchroniser sur la ligne actuelle</strong>.</li><li><strong>Minuterie de mise en veille, statistiques et éditeur de tags :</strong> minuteries de <code>5</code> à <code>90</code> minutes ou arrêt en fin de piste, statistiques d’écoute (<strong>Récents</strong>, <strong>Lectures</strong>, <strong>Pas écoutés récemment</strong>, <strong>Jamais</strong>, plus <strong>Top Artistes</strong> et <strong>Top Albums</strong>), édition directe des métadonnées et pochettes, contrôles média système et changement de langue à chaud (<code>English</code> / <code>简体中文</code>).</li></ul></li></ul><h2 id="extensions-javascript-multiplateformes" tabindex="-1">Extensions JavaScript multiplateformes <a class="header-anchor" href="#extensions-javascript-multiplateformes" aria-label="Permalink to &quot;Extensions JavaScript multiplateformes&quot;">​</a></h2><p>Plutôt que d’embarquer une WebView lourde pour prendre en charge les sources musicales personnelles ou communautaires, Musico exécute un unique script CommonJS (<code>.musico.js</code>) ou une archive ZIP (<code>.musicoext</code>) directement dans le moteur JS natif de chaque plateforme (<strong>JavaScriptCore</strong> sur Apple, <strong>QuickJS</strong> sur Android, <strong>Jint</strong> sur Windows) :</p><ul><li><strong>Revue explicite des permissions et connexion isolée :</strong> toute extension importée reste désactivée tant que l’utilisateur n’a pas inspecté la liste blanche de domaines <code>permissions.hosts</code> et les capacités déclarées (<code>&quot;cookie&quot;</code>, <code>&quot;qr_login&quot;</code>, <code>&quot;web_login&quot;</code>, <code>&quot;tree&quot;</code> ou <code>&quot;proxy&quot;</code>). La capacité <code>&quot;web_login&quot;</code>, associée au champ conditionnel <code>webLogin</code> du manifeste (<code>{ loginUrl, cookieDomains, requiredCookies?, userAgent? }</code>), ouvre une WebView système éphémère et isolée (<strong>WKWebView</strong> / <strong>Android WebView</strong> / <strong>WebView2</strong>) strictement dédiée à la capture du cookie de session — l’interface du lecteur reste 100 % native — en complément de l’import masqué de fichiers <code>cookies.txt</code>.</li><li><strong>Écosystème de plugins officiels (<code>v2026.11.26</code>) :</strong> les plugins officiels sont livrés sous forme de paquets prêts à importer couvrant <strong>YouTube Search</strong> <code>v1.2.0</code> (<code>web_login</code> + paliers de qualité), <strong>Bilibili Search</strong> <code>v1.2.0</code> (<code>qr_login</code> + palier Hi-Res/FLAC), <strong>NetEase Cloud Music</strong> <code>v1.2.0</code> (9 paliers de qualité + <code>qr_login</code>) et <strong>Apple Music</strong> <code>v1.0.1</code> (transmission du jeton Bearer sur <code>searchLyrics</code> + repli codecs/pochettes).</li><li><strong>Exploitation fiable et débogage :</strong> inclut des panneaux de réglages par extension, un journal glissant des 200 dernières entrées, une désactivation/désinstallation non destructive qui préserve les pistes de la bibliothèque et l’audio mis en cache, ainsi qu’un outil de conformité Node.js (<code>docs/extensions/tools/mock-runner.mjs</code>) pour vérifier les scripts d’extension en local.</li></ul><h2 id="distribution-et-ingenierie-des-versions" tabindex="-1">Distribution et ingénierie des versions <a class="header-anchor" href="#distribution-et-ingenierie-des-versions" aria-label="Permalink to &quot;Distribution et ingénierie des versions&quot;">​</a></h2><p>Les workflows GitHub Actions multiplateformes compilent, testent et publient les versions taguées (dernière : <code>v1.3.4</code>) pour toutes les cibles — générant un <code>.dmg</code> macOS Catalyst, un <code>.ipa</code> iOS non signé, des <code>.apk</code> Android release/debug, ainsi qu’un installateur NSIS Windows (<code>Setup.exe</code>) et une archive portable autonome <code>.zip</code> (conservant les données dans <code>.\\Data\\</code> lorsque <code>portable.txt</code> est présent). Un système de mise à jour intégré vérifie <code>releases/latest</code> avec contrôle <code>SHA256SUMS.txt</code> et option <strong>Ignorer cette version</strong> sous Windows, Android et macOS.</p><h2 id="depot-et-telechargements" tabindex="-1">Dépôt et téléchargements <a class="header-anchor" href="#depot-et-telechargements" aria-label="Permalink to &quot;Dépôt et téléchargements&quot;">​</a></h2><ul><li><strong>Documentation et portail plugins :</strong> <a href="https://musico.seanpnex.win/?lang=fr" target="_blank" rel="noreferrer">musico.seanpnex.win/?lang=fr</a> (Guide utilisateur, plugins officiels et API v1)</li><li><strong>Code source :</strong> <a href="https://github.com/SEANPNEX/Musico" target="_blank" rel="noreferrer">github.com/SEANPNEX/Musico</a> (licence MIT)</li><li><strong>Versions :</strong> <a href="https://github.com/SEANPNEX/Musico/releases/latest" target="_blank" rel="noreferrer">Dernières builds bureau et mobile</a></li><li><strong>Guide développeur extensions :</strong> <a href="https://musico.seanpnex.win/developers/?lang=fr" target="_blank" rel="noreferrer">musico.seanpnex.win/developers/?lang=fr</a> · <a href="https://github.com/SEANPNEX/Musico/blob/main/docs/extensions/README.md" target="_blank" rel="noreferrer">GitHub README</a></li></ul>',15))])}const f=t(c,[["render",d]]);export{b as __pageData,f as default};
